1988:    pub(crate) async fn refresh_runtime_config(&self, next_config: Config) {
1989:        // Refresh only the user layer from the incoming snapshot. Preserve thread-local
1990:        // layers such as request/session overrides that were present when this session
1991:        // was created.
1992:        let notify_config_contributors = !self.services.extensions.config_contributors().is_empty();
1993:        let (previous_config, new_config, config) = {
1994:            let mut state = self.state.lock().await;
1995:            let previous_config = notify_config_contributors
1996:                .then(|| self.build_effective_session_config(&state.session_configuration));
1997:            let mut config = (*state.session_configuration.original_config_do_not_use).clone();
1998:            config.active_project = next_config.active_project.clone();
1999:            config.config_layer_stack = config
2000:                .config_layer_stack
2001:                .with_user_layer_from(&next_config.config_layer_stack);
2002:            config.tool_suggest =
2003:                resolve_tool_suggest_config_from_layer_stack(&config.config_layer_stack);
2004:            config.mcp_servers = next_config.mcp_servers.clone();
2005:            config.mcp_oauth_credentials_store_mode = next_config.mcp_oauth_credentials_store_mode;
2006:            if let Err(err) = config.features.set_enabled(
2007:                Feature::SecretAuthStorage,
2008:                next_config.features.enabled(Feature::SecretAuthStorage),
2009:            ) {
2010:                warn!("failed to refresh MCP auth storage config: {err}");
2011:            }
2012:            let config = Arc::new(config);
2013:            state.session_configuration.original_config_do_not_use = Arc::clone(&config);
2014:            self.mark_mcp_runtime_dirty();
2015:            let new_config = notify_config_contributors
2016:                .then(|| self.build_effective_session_config(&state.session_configuration));
2017:            (previous_config, new_config, config)
2018:        };
2019:        self.emit_config_changed_contributors(previous_config.as_ref(), new_config.as_ref());
2020:        self.schedule_mcp_prewarm();
2021:        self.refresh_hooks(config).await;
2022:    }
