2024:    pub(crate) async fn refresh_hooks(&self, config: Arc<Config>) {
2025:        let environments = self.services.turn_environments.snapshot().await;
2026:        let hooks_config = build_hooks_config(
2027:            config.as_ref(),
2028:            self.services.plugins_manager.as_ref(),
2029:            environments.single_local_environment(),
2030:        )
2031:        .await;
2032:
2033:        let state = self.state.lock().await;
2034:        // A newer refresh may have updated the config while this hook build was in flight.
2035:        // Only publish hooks derived from the current config snapshot.
2036:        if Arc::ptr_eq(
2037:            &state.session_configuration.original_config_do_not_use,
2038:            &config,
2039:        ) {
2040:            let hooks = self.hooks().reconfigured(hooks_config);
2041:            self.services.hooks.store(Arc::new(hooks));
2042:        }
